/** Generated by scripts/build-wasm.mjs. Missing artifacts select the server. */
const loaders = import.meta.glob("./wasm-generated/nisaba_compile_wasm.js")

export function compilerArtifactPresent(): boolean {
  return Object.keys(loaders).length > 0
}

export async function loadCompiler(): Promise<{
  compile(request: string): string
}> {
  const loader = Object.values(loaders)[0]
  if (!loader) throw new Error("Browser compiler is not built")
  const module = await loader() as {
    default(): Promise<unknown>
    new_compile_workers(capacity: number, ttlMillis: number): { compile(request: string): string }
  }
  await module.default()
  return module.new_compile_workers(4, 1_800_000)
}
